from qiskit.circuit.library import efficient_su2, real_amplitudes

ansatz = efficient_su2(4, reps=2)
n = int(ansatz.num_parameters)
trimmed = int(efficient_su2(4, reps=2, skip_final_rotation_layer=True).num_parameters)
ry_only = int(real_amplitudes(4, reps=2).num_parameters)
claims = {"A": 8, "B": 12, "C": 16, "D": 24, "E": 32, "F": 0}
evidence = {}
proven = []
for k, c in claims.items():
    m = bool(n == c)
    evidence[k] = f"executed efficient_su2(4, reps=2).num_parameters = {n}; option {k} claims {c} -> match={m}"
    if m:
        proven.append(k)
evidence["B"] += f"  (real_amplitudes(4, reps=2), the ry-only ansatz, is the circuit with {ry_only} parameters)"
evidence["C"] += f"  (skip_final_rotation_layer=True drops it to {trimmed})"
ops = {g: int(v) for g, v in ansatz.count_ops().items()}
evidence["F"] += f"  (the returned circuit is still unbound: count_ops = {ops})"
emit_verdict({
    "answer": proven,
    "evidence": evidence,
    "observed": {
        "num_parameters": n,
        "count_ops": ops,
        "without_final_rotation_layer": trimmed,
        "real_amplitudes_params": ry_only,
    },
})
